//! Tests the exact disposable fixture generated by the pinned TikTools CLI.
use cloud_verifier::{verify, ExpectedRelease};
use std::{error::Error, path::PathBuf};
use tiktools_plugin_package::{KeyRole, KeysDocument};

fn main() -> Result<(), Box<dyn Error>> {
    let root = PathBuf::from(
        std::env::args_os()
            .nth(1)
            .ok_or("expected registry fixture directory")?,
    );
    let keys = KeysDocument::parse(&std::fs::read(root.join("keys.json"))?)?;
    // This trust source is deliberately confined to the disposable test fixture.
    // A production caller must use a separately approved key, never unverified keys.json.
    let key = keys
        .keys
        .iter()
        .find(|k| k.role == KeyRole::Publisher && k.publisher.as_deref() == Some("acme"))
        .ok_or("fixture publisher key missing")?;
    let index: serde_json::Value =
        serde_json::from_slice(&std::fs::read(root.join("index/ac/me/acme.hooks.json"))?)?;
    let artifact = &index["releases"][0]["artifacts"][0];
    let verified = verify(
        &root.join("packages/acme.hooks/acme.hooks-0.1.0.plugin"),
        ExpectedRelease {
            namespace: "acme",
            plugin_id: "acme.hooks",
            version: "0.1.0",
            target: "any",
            sha256: artifact["sha256"]
                .as_str()
                .ok_or("fixture digest missing")?,
        },
        key,
    )?;
    assert_eq!(verified.publisher_key_id, "fixture-acme");
    println!("disposable CLI-generated fixture verified");
    Ok(())
}
